namespace RaceDay.Api.Models;
public enum UserRole { Organiser, Participant }
public enum EventType { Run, Walk, Cycle }
public class User { public int Id {get;set;} public string FullName {get;set;}=""; public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; public UserRole Role {get;set;} public string? Phone {get;set;} public string? ProfileImageUrl {get;set;} public ICollection<Event> OrganisedEvents {get;set;}=new List<Event>(); public ICollection<Enrollment> Enrollments {get;set;}=new List<Enrollment>(); }
public class Event { public int Id {get;set;} public string Name {get;set;}=""; public string Description {get;set;}=""; public DateTime EventDate {get;set;} public string Location {get;set;}=""; public decimal DistanceKm {get;set;} public EventType EventType {get;set;} public string? BannerImageUrl {get;set;} public int OrganiserId {get;set;} public User Organiser {get;set;}=null!; public ICollection<Category> Categories {get;set;}=new List<Category>(); public ICollection<Enrollment> Enrollments {get;set;}=new List<Enrollment>(); }
public class Category { public int Id {get;set;} public int EventId {get;set;} public Event Event {get;set;}=null!; public string Name {get;set;}=""; public int? MinimumAge {get;set;} public int? MaximumAge {get;set;} public decimal? DistanceKm {get;set;} }
