public class Result { public int Id {get;set;} public int EnrollmentId {get;set;} public Enrollment Enrollment {get;set;}=null!; public TimeSpan FinishTime {get;set;} public int FinishingPosition {get;set;} public DateTime RecordedAt {get;set;}=DateTime.UtcNow; }
